import fs from 'node:fs';
import path from 'node:path';

const ROOT = 'C:/Users/dev/projects/agent-deck/lab/docs/evidence/phase-10/captures';

export function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else out.push(p);
  }
  return out;
}

export const RUNS = fs.readdirSync(ROOT).filter(n => fs.statSync(path.join(ROOT, n)).isDirectory());

export function transcripts() {
  const out = [];
  for (const run of RUNS) {
    const files = walk(path.join(ROOT, run)).filter(f => f.endsWith('.jsonl'));
    for (const f of files) {
      const raw = fs.readFileSync(f, 'utf8');
      const lines = raw.split('\n').filter(l => l.trim().length);
      const recs = lines.map((l, i) => {
        try { return JSON.parse(l); } catch (e) { return { __BAD: true, i, l }; }
      });
      out.push({ run, file: f, base: path.basename(f), recs, bytes: fs.statSync(f).size });
    }
  }
  return out;
}

export const T = transcripts();

// ---- claim 1: root vs subagent
let roots = 0, subs = 0, other = [];
for (const t of T) {
  const meta = t.recs.find(r => r.type === 'session_meta');
  const ts = meta?.payload?.thread_source;
  if (ts === 'user') roots++;
  else if (ts === 'subagent') subs++;
  else other.push([t.base, ts]);
}
console.log('C1 transcripts=%d roots=%d subagents=%d other=%j', T.length, roots, subs, other);

// bad lines
const bad = T.flatMap(t => t.recs.filter(r => r.__BAD).map(r => [t.base, r.i]));
console.log('C1 unparseable jsonl lines:', bad.length, JSON.stringify(bad));

// ---- claim 2: cli_version
const vers = {};
for (const t of T) {
  const v = t.recs.find(r => r.type === 'session_meta')?.payload?.cli_version;
  vers[v] = (vers[v] || 0) + 1;
}
console.log('C2 cli_version census:', JSON.stringify(vers));

// ---- claim 6/K.7 census over whole corpus
const pt = {};
let enc = 0, encC1 = 0, encAnyContent = 0;
for (const t of T) for (const r of t.recs) {
  if (r.type === 'response_item') {
    const ty = r.payload?.type;
    pt[ty] = (pt[ty] || 0) + 1;
    if (r.payload && Object.prototype.hasOwnProperty.call(r.payload, 'encrypted_content')) enc++;
    const c = r.payload?.content;
    if (Array.isArray(c)) {
      if (c[1] && typeof c[1] === 'object' && Object.prototype.hasOwnProperty.call(c[1], 'encrypted_content')) encC1++;
      for (const el of c) if (el && typeof el === 'object' && 'encrypted_content' in el) encAnyContent++;
    }
  }
}
console.log('C7 response_item payload.type census:', JSON.stringify(pt));
console.log('C7 payload.encrypted_content=%d  payload.content[1].encrypted_content=%d  anyContentIdx=%d', enc, encC1, encAnyContent);

// also census of top-level record types
const rt = {};
for (const t of T) for (const r of t.recs) rt[r.type] = (rt[r.type] || 0) + 1;
console.log('record type census:', JSON.stringify(rt));

