// codex-drive.mjs — Phase 10 (Codex kill gate) capture driver.
//
// Runs one `codex exec` probe in a scratch git repo, captures everything Codex
// writes about it, and copies the result under docs/evidence/phase-10/captures/<run>/.
//
// node: builtins only. Writes ONLY to:
//   - %USERPROFILE%\codex-probe\hooks.log        (truncated between runs; we own it)
//   - %USERPROFILE%\codex-probe\scratch\         (the agent's own workspace)
//   - lab/docs/evidence/phase-10/captures/<run>/ (the capture)
// It never writes under %USERPROFILE%\.codex.
//
// NEVER-OPENED LIST (K.11). These paths are named here only so the exclusion is
// auditable; nothing in this file reads them:
//   auth.json  .sandbox-secrets  *.sqlite  *.sqlite-wal  *.sqlite-shm  installation_id  cap_sid
// The snapshot walker below refuses them by name. `cap_sid` was not in the brief's
// list; it was found by running the predicate over the real directory (KILL-GATE K.11)
// and is refused because an unexplained file whose name reads as a security identifier
// is not something to walk into.
//
// Usage:
//   node lab/scripts/codex-drive.mjs <run-name> <prompt-file> [--codex-home <dir>]

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { spawn } from 'node:child_process';

const HOME = os.homedir();
const CODEX_DIR = path.join(HOME, '.codex');
const PROBE_DIR = path.join(HOME, 'codex-probe');
const SCRATCH = path.join(PROBE_DIR, 'scratch');
const HOOKS_LOG = path.join(PROBE_DIR, 'hooks.log');
const HERE = path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const CAPTURES = path.join(HERE, '..', 'docs', 'evidence', 'phase-10', 'captures');

// Files we refuse to open, ever. Matched on basename, case-insensitively.
const NEVER_OPEN_EXACT = new Set(['auth.json', 'installation_id', 'cap_sid']);
const NEVER_OPEN_DIRS = new Set(['.sandbox-secrets', '.sandbox', '.sandbox-bin', 'cache', 'tmp', '.tmp']);
const NEVER_OPEN_RE = /\.sqlite(-wal|-shm)?$/i;

function refused(name) {
  const n = name.toLowerCase();
  return NEVER_OPEN_EXACT.has(n) || NEVER_OPEN_DIRS.has(n) || NEVER_OPEN_RE.test(n);
}

function sha256File(p) {
  return crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
}

/** Recursive (name, size, mtimeMs) listing. Refused entries are listed by name only, never read. */
function snapshot(root) {
  const out = new Map();
  if (!fs.existsSync(root)) return out;
  const walk = (dir, rel) => {
    let entries;
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const e of entries) {
      const abs = path.join(dir, e.name);
      const r = rel ? `${rel}/${e.name}` : e.name;
      if (refused(e.name)) { out.set(r, { refused: true }); continue; }
      if (e.isDirectory()) { walk(abs, r); continue; }
      let st;
      try { st = fs.statSync(abs); } catch { continue; }
      out.set(r, { size: st.size, mtimeMs: st.mtimeMs });
    }
  };
  walk(root, '');
  return out;
}

